// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, ERC20} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    Token token;

    // minimal ERC20 counterparty so fillOrder's safeTransferFrom succeeds
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }

    // ERC1271 wallet so the test contract can be a valid order maker (no vm.sign)
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        token = new Token();
        token.approve(address(c), type(uint256).max);
        this.approve(address(c), type(uint256).max);
        vm.warp(1);
    }

    function testFuzz_property(
        bool isCall,
        bool isLong,
        uint256 nonce,
        uint256 strike,
        uint256 premium,
        uint256 duration
    ) public {
        nonce = bound(nonce, 0, type(uint128).max);
        strike = bound(strike, 0, type(uint128).max);
        premium = bound(premium, 0, type(uint128).max);
        duration = bound(duration, 0, 9999 days);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(this),
            isCall: isCall,
            isLong: isLong,
            baseAsset: address(token),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + 1,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256 positionId = c.fillOrder(order, "", floorAssetTokenIds);

        // Rule: a fill only ever stamps the expiration of the position it belongs to.
        // For a LONG fill the expiration lives under the long id (orderHash) and the
        // returned short-side positionId must have expiration 0. For a SHORT fill the
        // returned positionId IS the filled position and gets ts+duration.
        if (isLong) {
            assertTrue(c.positionExpirations(positionId) == 0, "short-side id must stay unstamped on long fill");
        } else {
            assertTrue(
                c.positionExpirations(positionId) == block.timestamp + duration,
                "short fill must stamp its own positionId"
            );
        }
    }
}

contract Token {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    constructor() {
        balanceOf[msg.sender] = type(uint256).max;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) allowance[from][msg.sender] = allowed - amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}
